269 | impl ArrayEncoder for AlreadyDictionaryEncoder {
270 |     fn encode(
271 |         &self,
272 |         data: DataBlock,
273 |         data_type: &DataType,
274 |         buffer_index: &mut u32,
275 |     ) -> Result<EncodedArray> {
276 |         let DataType::Dictionary(key_type, value_type) = data_type else {
277 |             panic!("Expected dictionary type");
278 |         };
279 | 
280 |         let dict_data = match data {
281 |             DataBlock::Dictionary(dict_data) => dict_data,
282 |             DataBlock::AllNull(all_null) => {
283 |                 // In 2.1 this won't happen, kind of annoying to materialize a bunch of nulls
284 |                 let indices = UInt8Array::from(vec![0; all_null.num_values as usize]);
285 |                 let indices = arrow_cast::cast(&indices, key_type.as_ref()).unwrap();
286 |                 let indices = indices.into_data();
287 |                 let values = new_null_array(value_type, 1);
288 |                 DictionaryDataBlock {
289 |                     indices: FixedWidthDataBlock {
290 |                         bits_per_value: key_type.byte_width() as u64 * 8,
291 |                         data: LanceBuffer::from(indices.buffers()[0].clone()),
292 |                         num_values: all_null.num_values,
293 |                         block_info: BlockInfo::new(),
294 |                     },
295 |                     dictionary: Box::new(DataBlock::from_array(values)),
296 |                 }
297 |             }
298 |             _ => panic!("Expected dictionary data"),
299 |         };
300 |         let declared_key_bits = key_type.byte_width() as u64 * 8;
301 |         if dict_data.indices.bits_per_value != declared_key_bits {
302 |             return Err(Error::invalid_input(format!(
303 |                 "dictionary indices use {} bits but the declared {} key type uses {} bits; the normalized dictionary has {} values",
304 |                 dict_data.indices.bits_per_value,
305 |                 key_type,
306 |                 declared_key_bits,
307 |                 dict_data.dictionary.num_values()
308 |             )));
309 |         }
310 |         let num_dictionary_items = dict_data.dictionary.num_values() as u32;
311 | 
312 |         let encoded_indices = self.indices_encoder.encode(
313 |             DataBlock::FixedWidth(dict_data.indices),
314 |             key_type,
315 |             buffer_index,
316 |         )?;
317 |         let encoded_items =
318 |             self.items_encoder
319 |                 .encode(*dict_data.dictionary, value_type, buffer_index)?;
320 | 
321 |         let encoded = DataBlock::Dictionary(DictionaryDataBlock {
322 |             dictionary: Box::new(encoded_items.data),
323 |             indices: encoded_indices.data.as_fixed_width().unwrap(),
324 |         });
325 | 
326 |         let encoding = ProtobufUtils::dict_encoding(
327 |             encoded_indices.encoding,
328 |             encoded_items.encoding,
329 |             num_dictionary_items,
330 |         );
331 | 
332 |         Ok(EncodedArray {
333 |             data: encoded,
334 |             encoding,
335 |         })
336 |     }
