1114 |     // This is where we do the work to actually shift the offsets and encode nulls
1115 |     // Note that the output is u64 and the input could be i32 OR i64.
1116 |     fn extend_offsets_vec_u64(
1117 |         dest: &mut Vec<u64>,
1118 |         offsets: &dyn Array,
1119 |         validity: Option<&BooleanArray>,
1120 |         // The offset of this list into the destination
1121 |         base: u64,
1122 |         null_offset_adjustment: u64,
1123 |     ) {
1124 |         match offsets.data_type() {
1125 |             DataType::Int32 => {
1126 |                 let offsets_i32 = offsets.as_primitive::<Int32Type>();
1127 |                 let start = offsets_i32.value(0) as u64;
1128 |                 // If we want to take a list from start..X and change it into
1129 |                 // a list from end..X then we need to add (base - start) to all elements
1130 |                 // Note that `modifier` may be negative but (item + modifier) will always be >= 0
1131 |                 let modifier = base as i64 - start as i64;
1132 |                 if let Some(validity) = validity {
1133 |                     dest.extend(
1134 |                         offsets_i32
1135 |                             .values()
1136 |                             .iter()
1137 |                             .skip(1)
1138 |                             .zip(validity.values().iter())
1139 |                             .map(|(&off, valid)| {
1140 |                                 (off as i64 + modifier) as u64
1141 |                                     + (!valid as u64 * null_offset_adjustment)
1142 |                             }),
1143 |                     );
1144 |                 } else {
1145 |                     dest.extend(
1146 |                         offsets_i32
1147 |                             .values()
1148 |                             .iter()
1149 |                             .skip(1)
1150 |                             // Subtract by `start` so offsets start at 0
1151 |                             .map(|&v| (v as i64 + modifier) as u64),
1152 |                     );
1153 |                 }
1154 |             }
1155 |             DataType::Int64 => {
1156 |                 let offsets_i64 = offsets.as_primitive::<Int64Type>();
1157 |                 let start = offsets_i64.value(0) as u64;
1158 |                 // If we want to take a list from start..X and change it into
1159 |                 // a list from end..X then we need to add (base - start) to all elements
1160 |                 // Note that `modifier` may be negative but (item + modifier) will always be >= 0
1161 |                 let modifier = base as i64 - start as i64;
1162 |                 if let Some(validity) = validity {
1163 |                     dest.extend(
1164 |                         offsets_i64
1165 |                             .values()
1166 |                             .iter()
1167 |                             .skip(1)
1168 |                             .zip(validity.values().iter())
1169 |                             .map(|(&off, valid)| {
1170 |                                 (off + modifier) as u64 + (!valid as u64 * null_offset_adjustment)
1171 |                             }),
1172 |                     )
1173 |                 } else {
1174 |                     dest.extend(
1175 |                         offsets_i64
1176 |                             .values()
1177 |                             .iter()
1178 |                             .skip(1)
1179 |                             .map(|&v| (v + modifier) as u64),
1180 |                     );
1181 |                 }
1182 |             }
1183 |             _ => panic!("Invalid list offsets data type {:?}", offsets.data_type()),
1184 |         }
1185 |     }
