1187 |     fn do_encode_u64(
1188 |         offset_arrays: Vec<ArrayRef>,
1189 |         validity: Vec<Option<&BooleanArray>>,
1190 |         num_offsets: u64,
1191 |         null_offset_adjustment: u64,
1192 |         buffer_index: &mut u32,
1193 |         inner_encoder: Arc<dyn ArrayEncoder>,
1194 |     ) -> Result<EncodedArray> {
1195 |         let mut offsets = Vec::with_capacity(num_offsets as usize);
1196 |         for (offsets_arr, validity_arr) in offset_arrays.iter().zip(validity) {
1197 |             let last_prev_offset = offsets.last().copied().unwrap_or(0) % null_offset_adjustment;
1198 |             Self::extend_offsets_vec_u64(
1199 |                 &mut offsets,
1200 |                 &offsets_arr,
1201 |                 validity_arr,
1202 |                 last_prev_offset,
1203 |                 null_offset_adjustment,
1204 |             );
1205 |         }
1206 |         let offsets_data = DataBlock::FixedWidth(FixedWidthDataBlock {
1207 |             bits_per_value: 64,
1208 |             data: LanceBuffer::reinterpret_vec(offsets),
1209 |             num_values: num_offsets,
1210 |             block_info: BlockInfo::new(),
1211 |         });
1212 |         inner_encoder.encode(offsets_data, &DataType::UInt64, buffer_index)
1213 |     }
