1215 |     fn do_encode(
1216 |         offset_arrays: Vec<ArrayRef>,
1217 |         validity_arrays: Vec<ArrayRef>,
1218 |         buffer_index: &mut u32,
1219 |         num_offsets: u64,
1220 |         inner_encoder: Arc<dyn ArrayEncoder>,
1221 |     ) -> Result<EncodedArray> {
1222 |         let validity_arrays = validity_arrays
1223 |             .iter()
1224 |             .map(|v| {
1225 |                 if v.is_empty() {
1226 |                     None
1227 |                 } else {
1228 |                     Some(v.as_boolean())
1229 |                 }
1230 |             })
1231 |             .collect::<Vec<_>>();
1232 |         debug_assert_eq!(offset_arrays.len(), validity_arrays.len());
1233 |         let total_span = offset_arrays
1234 |             .iter()
1235 |             .map(|arr| Self::get_offset_span(arr.as_ref()))
1236 |             .sum::<u64>();
1237 |         // See encodings.proto for reasoning behind this value
1238 |         let null_offset_adjustment = total_span + 1;
1239 |         let encoded_offsets = Self::do_encode_u64(
1240 |             offset_arrays,
1241 |             validity_arrays,
1242 |             num_offsets,
1243 |             null_offset_adjustment,
1244 |             buffer_index,
1245 |             inner_encoder,
1246 |         )?;
1247 |         Ok(EncodedArray {
1248 |             data: encoded_offsets.data,
1249 |             encoding: pb::ArrayEncoding {
1250 |                 array_encoding: Some(pb::array_encoding::ArrayEncoding::List(Box::new(
1251 |                     pb::List {
1252 |                         offsets: Some(Box::new(encoded_offsets.encoding)),
1253 |                         null_offset_adjustment,
1254 |                         num_items: total_span,
1255 |                     },
1256 |                 ))),
1257 |             },
1258 |         })
1259 |     }
