1297 | impl FieldEncoder for ListFieldEncoder {
1298 |     fn maybe_encode(
1299 |         &mut self,
1300 |         array: ArrayRef,
1301 |         external_buffers: &mut OutOfLineBuffers,
1302 |         repdef: RepDefBuilder,
1303 |         row_number: u64,
1304 |         num_rows: u64,
1305 |     ) -> Result<Vec<EncodeTask>> {
1306 |         // The list may have an offset / shorter length which means the underlying
1307 |         // values array could be longer than what we need to encode and so we need
1308 |         // to slice down to the region of interest.
1309 |         let items = match array.data_type() {
1310 |             DataType::List(_) => {
1311 |                 let list_arr = array.as_list::<i32>();
1312 |                 let items_start = list_arr.value_offsets()[list_arr.offset()] as usize;
1313 |                 let items_end =
1314 |                     list_arr.value_offsets()[list_arr.offset() + list_arr.len()] as usize;
1315 |                 list_arr
1316 |                     .values()
1317 |                     .slice(items_start, items_end - items_start)
1318 |             }
1319 |             DataType::LargeList(_) => {
1320 |                 let list_arr = array.as_list::<i64>();
1321 |                 let items_start = list_arr.value_offsets()[list_arr.offset()] as usize;
1322 |                 let items_end =
1323 |                     list_arr.value_offsets()[list_arr.offset() + list_arr.len()] as usize;
1324 |                 list_arr
1325 |                     .values()
1326 |                     .slice(items_start, items_end - items_start)
1327 |             }
1328 |             _ => panic!(),
1329 |         };
1330 |         let offsets_tasks = self
1331 |             .offsets_encoder
1332 |             .maybe_encode_offsets_and_validity(array.as_ref())
1333 |             .map(|task| vec![task])
1334 |             .unwrap_or_default();
1335 |         let mut item_tasks = self.items_encoder.maybe_encode(
1336 |             items,
1337 |             external_buffers,
1338 |             repdef,
1339 |             row_number,
1340 |             num_rows,
1341 |         )?;
1342 |         if !offsets_tasks.is_empty() && item_tasks.is_empty() {
1343 |             // An items page cannot currently be shared by two different offsets pages.  This is
1344 |             // a limitation in the current scheduler and could be addressed in the future.  As a result
1345 |             // we always need to encode the items page if we encode the offsets page.
1346 |             //
1347 |             // In practice this isn't usually too bad unless we are targeting very small pages.
